Given an integer array arr[] and an integer target, find the sum of triplets such that the sum is closest to target. Note: If there are multiple sums closest to target, print the maximum one.Examples:Input: arr[] = [-1, 2, 2, 4], target = 4Output: 5Explanation: All possible triplets[-1, 2, 2], sum = (-1) + 2 + 2 = 3[-1, 2, 4], sum = (-1) + 2 + 4 = 5[-1, 2, 4], sum = (-1) + 2 + 4 = 5[2, 2, 4], sum = 2 + 2 + 4 = 8Triplet [-1, 2, 2], [-1, 2, 4] and [-1, 2, 4] have sum closest to target, so return the maximum one, that is 5.Input: arr[] = [1, 10, 4, 5], target = 10Output: 10Explanation: All possible triplets[1, 10, 4], sum = (1 + 10 + 4) = 15[1, 10, 5], sum = (1 + 10 + 5) = 16[1, 4, 5], sum = (1 + 4 + 5) = 10[10, 4, 5], sum = (10 + 4 + 5) = 19Triplet [1, 4, 5] has sum = 10 which is closest to target.Try It YourselfTable of Content[Naive Approach] Explore all Triplets - O(n^3) Time and O(1) Space[Expected Approach] Sorting and Two Pointers – O(n^2) Time and O(1) Space[Naive Approach] Explore all Triplets - O(n^3) Time and O(1) SpaceA naive approach is to run three nested loops and keep track of the difference between target and the sum of the subset. Then, return the sum which is closest to target.
            C++

    #include <iostream>
#include <limits.h>
#include <vector>
using namespace std;

int closest3Sum(vector<int> &arr, int target) {
    int n = arr.size();
    int minDiff = INT_MAX;
    int res = 0;

    // Generating all possible triplets
    for (int i = 0; i < n - 2; i++) {
        for (int j = i + 1; j < n - 1; j++) {
            for (int k = j + 1; k < n; k++) {
                int currSum = arr[i] + arr[j] + arr[k];
                int currDiff = abs(currSum - target);

                // if currentDiff is less than minDiff, it indicates
                // that this triplet is closer to the target
                if (currDiff < minDiff) {
                    res = currSum;
                    minDiff = currDiff;
                }
                // If multiple sums are closest, take maximum one
                else if(currDiff == minDiff) {
                	res = max(res, currSum);
                }
            }
        }
    }

    return res;
}

int main() {
    vector<int> arr = {-1, 2, 2, 4};
    int target = 4;
    cout << closest3Sum(arr, target);
    return 0;
}


